'use strict';
const GC_COMPOUNDS=[
 {id:'isopropanol',name:'2-Propanol / isopropanol',formula:'C₃H₈O',bp:82.5,mw:60.095,carbon:3,k80:.75,polar:5.8,aromatic:false,response:.8,color:'#ba7051',nist:'C67630'},
 {id:'acetonitrile',name:'Acetonitrile',formula:'C₂H₃N',bp:81.6,mw:41.0519,carbon:2,k80:.4,polar:8,aromatic:false,response:.65,color:'#7c79b4',nist:'C75058'},
 {id:'ethylAcetate',name:'Ethyl acetate',formula:'C₄H₈O₂',bp:77.1,mw:88.1051,carbon:4,k80:.85,polar:3.2,aromatic:false,response:.7,color:'#a3894e',nist:'C141786'},
 {id:'dichloromethane',name:'Dichloromethane',formula:'CH₂Cl₂',bp:39.6,mw:84.933,carbon:1,k80:.2,polar:2,aromatic:false,response:.12,color:'#668d8b',nist:'C75092'},
 {id:'cyclohexane',name:'Cyclohexane',formula:'C₆H₁₂',bp:80.7,mw:84.1595,carbon:6,k80:1.6,polar:.6,aromatic:false,response:1,color:'#759847',nist:'C110827'},
 {id:'methanol',name:'Methanol',formula:'CH₄O',bp:64.7,mw:32.0419,carbon:1,k80:.12,polar:18,aromatic:false,response:.55,color:'#cc8651',nist:'C67561'},
 {id:'propanol',name:'1-Propanol',formula:'C₃H₈O',bp:97.2,mw:60.095,carbon:3,k80:1.3,polar:12,aromatic:false,response:.8,color:'#457fb6',nist:'C71238'},
 {id:'acetone',name:'Acetone',formula:'C₃H₆O',bp:56.1,mw:58.0791,carbon:3,k80:.38,polar:4,aromatic:false,response:.8,color:'#be7647',nist:'C67641'},
 {id:'ethanol',name:'Ethanol',formula:'C₂H₆O',bp:78.4,mw:46.0684,carbon:2,k80:.32,polar:15,aromatic:false,response:.7,color:'#9670bc',nist:'C64175'},
 {id:'hexane',name:'n-Hexane',formula:'C₆H₁₄',bp:68.7,mw:86.1754,carbon:6,k80:1,polar:.55,aromatic:false,response:1,color:'#388f9b',nist:'C110543'},
 {id:'heptane',name:'n-Heptane',formula:'C₇H₁₆',bp:98.4,mw:100.2019,carbon:7,k80:3,polar:.55,aromatic:false,response:1,color:'#53904f',nist:'C142825'},
 {id:'toluene',name:'Toluene',formula:'C₇H₈',bp:110.6,mw:92.1384,carbon:7,k80:4.2,polar:1.7,aromatic:true,response:1,color:'#4772b2',nist:'C108883'},
 {id:'octane',name:'n-Octane',formula:'C₈H₁₈',bp:125.6,mw:114.2285,carbon:8,k80:6,polar:.55,aromatic:false,response:1,color:'#ba585e',nist:'C111659'},
 {id:'ethylbenzene',name:'Ethylbenzene',formula:'C₈H₁₀',bp:136.2,mw:106.165,carbon:8,k80:8.5,polar:1.9,aromatic:true,response:1,color:'#8c8650',nist:'C100414'},
 {id:'decane',name:'n-Decane',formula:'C₁₀H₂₂',bp:174.1,mw:142.2817,carbon:10,k80:20,polar:.55,aromatic:false,response:1,color:'#886b5b',nist:'C124185'}
];
const GC_COLUMNS={pdms:{name:'PDMS · nonpolar',limit:320},phenyl:{name:'5% phenyl / 95% PDMS · low polarity',limit:320},wax:{name:'PEG / WAX · polar',limit:230}};
function gcDefaults(){return {detectorType:'fid',msSource:230,msQuad:150,msTransfer:280,gas:'helium',injectionTime:1,column:'phenyl',length:30,id:.25,film:.25,injector:250,detector:280,volume:1,splitMode:'split',split:50,flow:1,ovenMode:'program',initial:40,hold:1,ramp:10,final:180,finalHold:3,runtime:15,noise:true}}
const gc={method:gcDefaults(),mix:{hexane:.5,heptane:.5,toluene:.5,octane:.5,ethylbenzene:.5},sample:'hydrocarbons',actualInjector:25,actualDetector:25,actualOven:25,power:false,carrier:false,ready:false,flame:false,warming:false,warm:0,running:false,paused:false,run:null,time:0,speed:60,selected:null,message:'Set the method, power on, turn on carrier gas, equilibrate, then ignite the FID and inject.',history:[],raf:0};
try{const saved=JSON.parse(localStorage.getItem('simlab-gcfid')||'null');if(saved){gc.method={...gcDefaults(),...saved.method};gc.history=Array.isArray(saved.history)?saved.history.slice(-8):[];if(saved.mix&&typeof saved.mix==='object'){gc.mix={};for(const c of GC_COMPOUNDS)if(Number.isFinite(Number(saved.mix[c.id]))&&Number(saved.mix[c.id])>0&&Number(saved.mix[c.id])<=20)gc.mix[c.id]=Number(saved.mix[c.id]);gc.sample=saved.sample||'custom'}}}catch{}
function gcNumber(x){return Number.isFinite(Number(x))}
function gcFmt(n,d=3){return Number.isFinite(n)?n.toFixed(d):'—'}
function gcDuration(m){return m.ovenMode==='program'?m.hold+(m.final-m.initial)/m.ramp+m.finalHold:m.runtime}
function gcOven(m,t){return m.ovenMode==='program'?t<=m.hold?m.initial:Math.min(m.final,m.initial+(t-m.hold)*m.ramp):m.initial}
function gcValidation(m){const errors=[];const bounds={msSource:[150,300],msQuad:[100,200],msTransfer:[150,320],injectionTime:[.1,10],length:[5,100],id:[.1,.53],film:[.1,2],injector:[40,350],detector:[151,400],volume:[.1,5],flow:[.2,5],initial:[30,320],hold:[0,20],ramp:[.5,50],final:[30,320],finalHold:[0,30],runtime:[1,90],split:[1,200]};for(const[k,[low,high]]of Object.entries(bounds)){if((!gcIsMS(m)&&['msSource','msQuad','msTransfer'].includes(k))||(gcIsMS(m)&&k==='detector'))continue;if(m.ovenMode==='program'&&k==='runtime'||m.ovenMode==='isothermal'&&['hold','ramp','final','finalHold'].includes(k)||m.splitMode==='splitless'&&k==='split')continue;if(!gcNumber(m[k])||Number(m[k])<low||Number(m[k])>high)errors.push(`${k}: enter a value from ${low} to ${high}.`)}if(!['fid','ms'].includes(m.detectorType||'fid'))errors.push('Select FID or MS as the detector.');if(gcIsMS(m)&&m.gas!=='helium')errors.push('This GC-MS teaching configuration uses helium carrier gas.');if(!['helium','hydrogen','nitrogen'].includes(m.gas||'helium'))errors.push('Choose a supported carrier gas.');if(!GC_COLUMNS[m.column])errors.push('Choose a supported stationary phase.');if(!['program','isothermal'].includes(m.ovenMode))errors.push('Choose an oven mode.');if(!['split','splitless'].includes(m.splitMode))errors.push('Choose split or splitless injection.');if(m.ovenMode==='program'&&m.final<m.initial)errors.push('Final oven temperature must be at least the initial temperature.');const max=m.ovenMode==='program'?Math.max(m.initial,m.final):m.initial;if(GC_COLUMNS[m.column]&&max>GC_COLUMNS[m.column].limit)errors.push(`The selected simulated column is limited to ${GC_COLUMNS[m.column].limit} °C.`);if(!Number.isFinite(gcDuration(m))||gcDuration(m)>120)errors.push('Keep the total run time at or below 120 minutes.');return errors}
function gcSamples(){return GC_COMPOUNDS.filter(c=>Number(gc.mix[c.id])>0).map(c=>({...c,concentration:Number(gc.mix[c.id])}))}
function gcPhaseRatio(m){const radius=m.id*500,film=m.film;return (radius*radius-(radius-film)**2)/(radius-film)**2}
function gcRetention(c,m,temp){const selectivity=m.column==='wax'?c.polar:m.column==='phenyl'&&c.aromatic?1.22:1,phase=gcPhaseRatio(m)/gcPhaseRatio({id:.25,film:.25}),thermal=2700+c.bp*3+353.15*Math.log(selectivity);return Math.max(.0001,c.k80*selectivity*phase*Math.exp(thermal*(1/(temp+273.15)-1/353.15)))}
function gcColumnMetrics(m){const radius=m.id/20-m.film/10000,area=Math.PI*radius*radius,velocity=m.flow/(60*area),optimal={helium:35,hydrogen:45,nitrogen:12}[m.gas||'helium'],reduced=velocity/optimal,height=.025*(m.id/.25)*(1/reduced+reduced)+.004*(m.film/.25)**2*reduced;return {velocity,efficiency:Math.max(500,m.length*100/height),holdup:area*m.length*100/m.flow,capacity:100*(m.id/.25)*(m.film/.25)}}
function gcBaseline(t){return 2+.008*t}
function gcIntegratePeaks(times,signal,components,dt,noise){const n=times.length,corrected=signal.map((v,i)=>v-gcBaseline(times[i])),smooth=new Float64Array(n);for(let i=0;i<n;i++){let sum=0,count=0;for(let j=Math.max(0,i-2);j<=Math.min(n-1,i+2);j++){sum+=corrected[j];count++}smooth[i]=sum/count}const threshold=noise?.18:.05,candidates=[];for(let i=3;i<n-3;i++)if(smooth[i]>threshold&&smooth[i]>smooth[i-1]&&smooth[i]>=smooth[i+1])candidates.push(i);let peaks=[];for(const at of candidates){if(!peaks.length){peaks.push(at);continue}let last=peaks.at(-1),valley=Infinity;for(let j=last;j<=at;j++)valley=Math.min(valley,smooth[j]);const small=Math.min(smooth[last],smooth[at]);if((at-last)*dt<.012||valley>.85*small){if(smooth[at]>smooth[last])peaks[peaks.length-1]=at}else peaks.push(at)}let rows=[];for(let p=0;p<peaks.length;p++){const at=peaks[p],cutoff=Math.max(noise?.07:.001,smooth[at]*.002);let left=at,right=at;while(left>0&&smooth[left]>cutoff)left--;while(right<n-1&&smooth[right]>cutoff)right++;if(p>0){let valley=at;for(let j=peaks[p-1];j<=at;j++)if(smooth[j]<smooth[valley])valley=j;left=Math.max(left,valley)}if(p<peaks.length-1){let valley=at;for(let j=at;j<=peaks[p+1];j++)if(smooth[j]<smooth[valley])valley=j;right=Math.min(right,valley)}let apex=at,area=0;for(let j=left;j<=right;j++){if(corrected[j]>corrected[apex])apex=j;if(j<right)area+=(corrected[j]+corrected[j+1])*.5*(times[j+1]-times[j])*60}let half=corrected[apex]/2,l=apex,r=apex;while(l>left&&corrected[l]>half)l--;while(r<right&&corrected[r]>half)r++;const members=components.filter(c=>c.tr!==null&&c.tr>=times[left]&&c.tr<=times[right]);rows.push({number:p+1,index:apex,tr:times[apex],height:corrected[apex],area:Math.max(0,area),left:times[left],right:times[right],width:times[r]-times[l],members:members.map(c=>c.name),ids:members.map(c=>c.id),partial:right===n-1,resolution:null})}for(let i=1;i<rows.length;i++){const rs=1.18*(rows[i].tr-rows[i-1].tr)/Math.max(1e-8,rows[i].width+rows[i-1].width);rows[i].resolution=rs;rows[i].overlap=rs<1.5;rows[i-1].overlap=rows[i-1].overlap||rs<1.5}return rows}
function gcSimulate(m,input){m={...m};for(const [key,value]of Object.entries(gcDefaults()))if(typeof value==='number')m[key]=Number(m[key]);if(input.some(c=>!Number.isFinite(c.concentration)||c.concentration<=0||c.concentration>20))throw Error('Use positive sample concentrations up to 20 mg/mL.');const errors=gcValidation(m);if(errors.length)throw Error(errors.join(' '));const duration=gcDuration(m),steps=Math.ceil(duration/Math.max(.001,duration/40000)),dt=duration/steps,times=Float64Array.from({length:steps+1},(_,i)=>i*dt),metrics=gcColumnMetrics(m),holdup=metrics.holdup,efficiency=metrics.efficiency,velocity=metrics.velocity;const divisor=m.splitMode==='split'?m.split+1:1;const components=input.map(c=>{const transfer=1/(1+Math.exp((c.bp+15-m.injector)/12)),mass=c.concentration*m.volume*1000/divisor*transfer;return {...c,mass,transfer,tr:null,positions:new Float32Array(steps+1),area:3*mass*(c.carbon*12.011/c.mw)*c.response}});for(const c of components){let x=0;for(let i=1;i<=steps;i++){let v=dt/(holdup*(1+gcRetention(c,m,gcOven(m,times[i]-.5*dt))));if(c.tr===null&&x+v>=1)c.tr=times[i-1]+dt*(1-x)/v;x=Math.min(1,x+v);c.positions[i]=x}c.sigma=c.tr===null?null:Math.sqrt(Math.max(.003,c.tr/Math.sqrt(efficiency))**2+((m.injectionTime||1)/60/Math.sqrt(12))**2*m.volume)*(1+Math.max(0,c.mass/metrics.capacity-1)*2/3)**.35*(1+(1-c.transfer)*2);c.height=c.sigma?c.area/(c.sigma*60*Math.sqrt(2*Math.PI)):0}const signal=Float64Array.from(times,t=>{let y=gcBaseline(t);if(m.noise)y+=.025*Math.sin(97*t)+.013*Math.sin(241*t+.4);for(const c of components)if(c.tr!==null){let z=(t-c.tr)/c.sigma;if(Math.abs(z)<8)y+=c.height*Math.exp(-.5*z*z)}return y});const peaks=gcIntegratePeaks(times,signal,components,dt,m.noise),warnings=[];if(components.some(c=>c.transfer<.9))warnings.push('Low injector temperature reduces transfer of some components and broadens their bands in this model.');if(components.some(c=>c.mass>metrics.capacity))warnings.push('High on-column loading causes modelled broadening. Reduce injection volume or concentration, or increase the split ratio.');if(components.some(c=>c.tr===null))warnings.push('Some components do not elute within the selected run. Increase time or oven temperature within the column limit.');if(peaks.some(p=>p.members.length>1||p.overlap))warnings.push('Some peaks overlap. Their integrated areas may contain contributions from more than one compound.');if(peaks.some(p=>p.partial))warnings.push('A peak is cut off by the end of the run; its area is incomplete.');if(!gcIsMS(m)&&m.detector<(m.ovenMode==='program'?m.final:m.initial)+20)warnings.push('The FID temperature is close to the oven maximum; a warmer detector is commonly used to reduce condensation.');return {method:{...m},duration,dt,times,signal,components,peaks,warnings,holdup,efficiency,velocity}}
function gcSave(){try{localStorage.setItem('simlab-gcfid',JSON.stringify({method:gc.method,history:gc.history,mix:gc.mix,sample:gc.sample}));return true}catch{return false}}
function gcRender(){gcSave();if(typeof page!=='undefined'&&page==='instrumentation')render()}
function gcIsMS(m=gc.method){return m?.detectorType==='ms'}
function gcDetectorReady(){return gcIsMS()?typeof gcMSReady==='function'&&gcMSReady():gc.flame}
function gcSignalText(){return gcIsMS(gc.run?.method||gc.method)?(typeof gcMSDataSignal==='function'?gcMSDataSignal():'0.00 a.u.'):gcFmt(gc.flame?(gc.run?gc.run.signal[gcIndex()]:2):0,2)+' pA'}
function gcLocked(){return gc.running||gc.paused||gc.warming||(typeof gms!=='undefined'&&gms.pumping)}
function gcField(label,key,min,max,step='any'){return `<label class="gc-field">${label}<input data-gc-field="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${gc.method[key]}" ${gcLocked()||gseq.active?'disabled':''}></label>`}
function gcSelect(label,key,options){return `<label class="gc-field">${label}<select data-gc-field="${key}" ${gcLocked()||gseq.active?'disabled':''}>${options.map(([value,name])=>`<option value="${value}" ${String(gc.method[key])===String(value)?'selected':''}>${name}</option>`).join('')}</select></label>`}
function gcIndex(){return gc.run?Math.min(gc.run.times.length-1,Math.max(0,Math.floor(gc.time/gc.run.dt))):0}
function gcVisiblePeaks(){return gc.run?gc.run.peaks.filter(p=>p.right<=gc.time+1e-8):[]}
function gcStatus(){return !gc.power?'POWER OFF':gc.warming?'EQUILIBRATING':gc.running?'ACQUIRING':gc.paused?'PAUSED':gc.run?.completed&&!gc.preparingNext?'RUN COMPLETE':!gc.carrier?'CARRIER OFF':!gc.ready?'NOT READY':!gcDetectorReady()?(gcIsMS()?'MS NOT READY':'FID OFF'):'READY'}
function instrumentation(){const m=gc.method,locked=gcLocked()||gseq.active,r=gc.run;return `${head('INSTRUMENTATION','GC instrument workbench','Prepare a method, inject a volatile sample and follow its separation from injector to detector.')}<div class="gc-actions"><a class="btn secondary small" href="#gcCalibration">Calibration results ↓</a></div>${gcSequencePanel()}<div class="gc-layout"><aside class="gc-controls"><section class="panel gc-panel"><span class="eyebrow">01 · METHOD & COLUMN</span><h2>Set up the separation</h2>${gcSelect('Acquisition detector','detectorType',[['fid','FID · flame ionization'],['ms','MS · electron ionization']])}${gcSelect('Column stationary phase','column',Object.entries(GC_COLUMNS).map(([id,c])=>[id,c.name]))}<div class="gc-two">${gcField('Column length / m','length',5,100)}${gcSelect('Internal diameter / mm','id',[[.25,'0.25'],[.32,'0.32'],[.53,'0.53']])}${gcSelect('Film thickness / µm','film',[[.1,'0.10'],[.25,'0.25'],[.5,'0.50'],[1,'1.00']])}${gcSelect('Carrier gas','gas',[['helium','Helium'],['hydrogen','Hydrogen'],['nitrogen','Nitrogen']])}${gcField('Carrier flow / mL min⁻¹','flow',.2,5)}</div><span class="gc-phase-chip">Simulated column limit: ${GC_COLUMNS[m.column]?.limit??'—'} °C</span><p>Stationary-phase polarity changes selectivity. Longer columns and lower flow extend the time spent in the column.</p></section><section class="panel gc-panel"><span class="eyebrow">02 · TEMPERATURES</span><h2>Injector &amp; oven</h2><div class="gc-two">${gcField('Injector / °C','injector',40,350)}${gcIsMS()?gcField('MS source / °C','msSource',150,300)+gcField('MS quadrupole / °C','msQuad',100,200)+gcField('MS transfer line / °C','msTransfer',150,320):gcField('FID / °C','detector',151,400)}</div>${gcSelect('Oven mode','ovenMode',[['program','Temperature program'],['isothermal','Isothermal']])}${gcField(m.ovenMode==='program'?'Initial oven / °C':'Oven / °C','initial',30,320)}${m.ovenMode==='program'?`<div class="gc-two">${gcField('Initial hold / min','hold',0,20)}${gcField('Ramp / °C min⁻¹','ramp',.5,50)}${gcField('Final oven / °C','final',30,320)}${gcField('Final hold / min','finalHold',0,30)}</div>`:gcField('Run duration / min','runtime',1,90)}<p>Method duration: <b id="gcDuration">${gcFmt(gcDuration(m),2)} min</b>. A warmer oven generally reduces retention; overly fast elution can reduce separation.</p></section><section class="panel gc-panel"><span class="eyebrow">03 · SAMPLE & INJECTION</span><h2>Load sample &amp; inject</h2>${gcSampleLoader()}<details><summary>Reference / demonstration samples</summary><label class="gc-field">Sample<select id="gcSample" ${locked?'disabled':''}><option value="hydrocarbons" ${gc.sample==='hydrocarbons'?'selected':''}>Hydrocarbon reference mixture</option><option value="polarity" ${gc.sample==='polarity'?'selected':''}>Polarity comparison mixture</option>${GC_COMPOUNDS.map(c=>`<option value="${c.id}" ${gc.sample===c.id?'selected':''}>${c.name} standard</option>`).join('')}<option value="custom" ${gc.sample==='custom'?'selected':''}>Custom mixture</option><option value="blank" ${gc.sample==='blank'?'selected':''}>Blank · baseline only</option></select></label><details><summary>Compounds &amp; concentrations</summary><p>Concentration is in mg/mL for each component. The sample solvent peak is omitted in this teaching model.</p>${GC_COMPOUNDS.map(c=>`<div class="gc-sample-row"><label><input type="checkbox" data-gc-compound="${c.id}" ${Number(gc.mix[c.id])>0?'checked':''} ${locked?'disabled':''}>${c.name}</label><input aria-label="${c.name} concentration in mg per mL" data-gc-concentration="${c.id}" type="number" min="0.001" max="20" step="any" value="${gc.mix[c.id]??.5}" ${locked||!(Number(gc.mix[c.id])>0)?'disabled':''}></div>`).join('')}</details></details><div class="gc-two">${gcField('Injection volume / µL','volume',.1,5)}${gcField('Injection duration / s','injectionTime',.1,10)}${gcSelect('Injection mode','splitMode',[['split','Split'],['splitless','Splitless']])}</div>${m.splitMode==='split'?gcField('Split ratio / x : 1','split',1,200):'<p>Splitless is modelled as full transfer to the column. Large amounts may overload it.</p>'}<label class="gc-check"><input id="gcNoise" type="checkbox" ${m.noise?'checked':''} ${locked?'disabled':''}>Simulated baseline noise</label><div class="gc-actions"><button class="btn secondary small" data-gc-action="demo" ${locked?'disabled':''}>Reset to demonstration method</button></div></section></aside><div><section class="panel gc-panel"><div class="gc-titlebar"><div><span class="eyebrow">VIRTUAL GAS CHROMATOGRAPH</span><h2>Injector → column → ${gcIsMS()?'MS':'FID'}</h2></div><span id="gcState" class="pill ${gc.running?'gc-running':''}">${gcStatus()}</span></div><div id="gcInstrument" class="gc-stage">${gcInstrument()}</div><div class="gc-actions"><button class="btn secondary" data-gc-action="power" ${locked?'disabled':''}>${gc.power?'Power off':'Power on'}</button><button class="btn secondary" data-gc-action="carrier" ${!gc.power||locked?'disabled':''}>${gc.carrier?'Carrier gas: ON':'Turn carrier gas on'}</button><button class="btn soft" data-gc-action="equilibrate" ${!gc.power||!gc.carrier||locked?'disabled':''}>Equilibrate temperatures</button><button ${gcIsMS()?'hidden':''} class="btn soft" data-gc-action="flame" ${(!gc.ready&&!gc.flame)||locked?'disabled':''}>${gc.flame?'Extinguish FID':'Ignite FID'}</button></div>${gcIsMS()&&typeof gcMSPanel==='function'?gcMSPanel(false):''}<p ${gcIsMS()?'hidden':''} class="gc-click-note">The virtual FID uses fixed detector hydrogen (40 mL/min), air (450 mL/min) and makeup flow. These are simulated supplies; the control sequence is a training abstraction.</p><div class="gc-notice" id="gcMessage" role="status" aria-live="polite">${gc.message}</div><div class="gc-stats"><div class="gc-stat"><small>Run time</small><b id="gcTime">${gcFmt(gc.time,2)} min</b></div><div class="gc-stat"><small>Oven now</small><b id="gcOvenValue">${gcFmt(gcActualOven(),1)} °C</b></div><div class="gc-stat"><small>${gcIsMS(r?.method||gc.method)?'TIC signal':'FID signal'}</small><b id="gcSignal">${gcSignalText()}</b></div><div class="gc-stat"><small>Integrated peaks</small><b id="gcPeakCount">${gcIsMS(r?.method)&&typeof gcMSPeakCount==='function'?gcMSPeakCount():gcVisiblePeaks().length}</b></div></div><progress class="gc-progress" id="gcProgress" max="1" value="${r?gc.time/r.duration:0}" aria-label="Chromatographic run progress"></progress><div class="gc-actions"><button class="btn" data-gc-action="inject" ${!gc.power||!gc.carrier||!gc.ready||!gcDetectorReady()||locked?'disabled':''}>Inject &amp; start run</button><button class="btn secondary" data-gc-action="pause" ${!gc.running&&!gc.paused?'disabled':''}>${gc.paused?'Resume':'Pause'}</button><button class="btn secondary" data-gc-action="stop" ${!gc.running&&!gc.paused?'disabled':''}>Stop acquisition</button><label class="gc-check">Playback <select id="gcSpeed">${[15,30,60,120].map(v=>`<option value="${v}" ${gc.speed===v?'selected':''}>${v}×</option>`).join('')}</select></label></div><div class="gc-legend">${(r?r.components:gcSamples()).map(c=>`<span><i style="background:${c.color}"></i>${c.name}</span>`).join('')}</div></section><section class="panel gc-panel"><div class="gc-titlebar"><div><span class="eyebrow">LIVE DATA ACQUISITION</span><h2>${gcIsMS(r?.method)?'MS ion chromatogram':'Chromatogram'}</h2></div><span class="pill">${gcIsMS(r?.method)?'SIMULATED MS TIC':'SIMULATED FID RESPONSE'}</span></div>${r?`<p class="gc-click-note">Acquired method: ${GC_COLUMNS[r.method.column].name} · injector ${r.method.injector} °C · ${r.method.volume} µL · ${r.method.ovenMode==='program'?r.method.initial+' → '+r.method.final+' °C':r.method.initial+' °C'} · flow ${r.method.flow} mL/min. Changing controls prepares the next run.</p>`:''}<div id="gcChart" class="gc-chart">${gcChart()}</div><p class="gc-click-note">The trace advances with the run. Peak labels and measurements appear once the peak’s integration window has passed. Select a row to highlight its integration window.</p><div id="gcResults">${gcResults()}</div><div class="gc-actions"><button class="btn secondary small" data-gc-action="save" ${gcIsMS(r?.method)?'hidden':''} ${!r||gc.running||gc.paused||r.saved?'disabled':''}>Save run summary</button><button class="btn secondary small" data-gc-action="export-peaks" ${gcIsMS(r?.method)?'hidden':''} ${!r||!gcVisiblePeaks().length?'disabled':''}>Export peak table CSV</button><button class="btn secondary small" data-gc-action="export-trace" ${gcIsMS(r?.method)?'hidden':''} ${!r||gc.time<=0?'disabled':''}>Export acquired trace CSV</button></div><div class="gc-actions"><button class="btn secondary small" data-go="massspec">Open MS instrument &amp; data</button></div><div id="gcWarnings">${gcWarnings()}</div>${typeof gcSeparationGuide==='function'?gcSeparationGuide():''}</section>${!gcIsMS()&&typeof gcCalibrationPanel==='function'?gcCalibrationPanel():''}<section class="panel gc-panel"><h2>Run notebook</h2>${gcHistory()}<details class="gc-detail"><summary>How the measurements and simulation work</summary><p>Retention time is the time from injection to a measured signal maximum. Peak height is baseline-corrected signal at that maximum. Area is trapezoidal integration of the acquired signal above the known simulated baseline; time is converted to seconds, giving pA·s. Area % refers only to integrated signal, not concentration or mass %.</p><p>The detector trace is the sum of Gaussian bands plus an optional reproducible baseline/noise signal. Integration detects maxima in a lightly smoothed trace, separates adjacent peaks at valleys, and flags insufficient resolution or multiple model components in a peak. Co-elution can prevent a reliable individual component area. Component names are assignments from the known simulated sample, not proof of identification from FID alone.</p><p>The migration model numerically integrates dx/dt = 1/[tM(1+k(T))]. Retention factors use teaching anchors at 80 °C, temperature-dependent phase selectivity and stationary/mobile-phase volume ratios; they are not measured retention factors. Column hold-up time uses column volume and set flow. Efficiency uses an illustrative open-tubular diffusion / mass-transfer curve with gas-dependent optimum velocity; film thickness, injection duration, transfer loss and on-column loading affect band width. These terms and carbon-sensitive FID response are simplified illustrative models, not instrument calibration. Pressure/compressibility, solvent expansion, decomposition, adsorption and many real method effects are not fully modelled. Instrument-specific work requires its own validated method.</p><p>Instrument principles and example FID operating conditions: <a href="https://www.agilent.com/cs/library/usermanuals/public/G3430-90015.pdf" target="_blank" rel="noopener">Agilent GC advanced operation manual</a>. Compound identities and approximate boiling points: NIST Chemistry WebBook.</p><div class="gc-table-wrap"><table class="gc-table"><thead><tr><th>Compound</th><th>Formula</th><th>Approx. boiling point / °C</th><th>Reference</th></tr></thead><tbody>${GC_COMPOUNDS.map(c=>`<tr><td>${c.name}</td><td>${c.formula}</td><td>${c.bp}</td><td><a href="https://webbook.nist.gov/cgi/cbook.cgi?ID=${c.nist}&amp;Mask=4" target="_blank" rel="noopener">NIST</a></td></tr>`).join('')}</tbody></table></div><p>All chromatographic retention times, response units and areas in this workbench are simulated teaching outputs. The conservative temperature limits shown apply to these simulated column choices.</p></details></section></div></div>`}
function gcActualOven(){if(gc.warming)return (gc.warmFrom?.oven??25)+(gc.method.initial-(gc.warmFrom?.oven??25))*gc.warm;if((gc.running||gc.paused)&&gc.run)return gcOven(gc.run.method,gc.time);return gc.actualOven??25}
function gcBandPoint(x){const pts=[[250,67],[538,67],[538,94],[250,94],[250,121],[538,121],[538,148],[250,148],[250,175],[538,175]],lengths=pts.slice(1).map((p,i)=>Math.hypot(p[0]-pts[i][0],p[1]-pts[i][1])),total=lengths.reduce((a,b)=>a+b,0);let d=Math.max(0,Math.min(1,x))*total;for(let i=0;i<lengths.length;i++){if(d<=lengths[i]){let f=d/lengths[i];return [pts[i][0]+(pts[i+1][0]-pts[i][0])*f,pts[i][1]+(pts[i+1][1]-pts[i][1])*f]}d-=lengths[i]}return pts.at(-1)}
function gcInstrument(){if(gcIsMS()&&typeof gcMSInstrument==='function')return gcMSInstrument();const r=gc.run,idx=gcIndex(),m=r&&(gc.running||gc.paused)?r.method:gc.method,oven=gcActualOven(),temp=(value,zone)=>{const actual=zone==='injector'?gc.actualInjector:gc.actualDetector,from=gc.warmFrom?.[zone]??actual??25;return gc.warming?from+(value-from)*gc.warm:actual??25};return `<svg viewBox="0 0 800 260" role="img" aria-label="GC-FID schematic: injector ${gcFmt(temp(m.injector,'injector'),0)} degrees, oven ${gcFmt(oven,0)} degrees, FID ${gc.flame?'lit':'off'}"><rect x="38" y="35" width="143" height="155" rx="13" fill="#fff" stroke="#b3cbbc"/><rect x="215" y="20" width="370" height="207" rx="15" fill="#e1ede4" stroke="#a7bda9"/><rect x="618" y="35" width="145" height="155" rx="13" fill="#fff" stroke="#b3cbbc"/><text x="110" y="60" text-anchor="middle" font-size="12" fill="#526f5b">INJECTOR</text><text x="400" y="42" text-anchor="middle" font-size="12" fill="#526f5b">COLUMN OVEN · ${GC_COLUMNS[m.column]?.name||''}</text><text x="690" y="60" text-anchor="middle" font-size="12" fill="#526f5b">FID</text><path d="M110 82V130H250V67H538V94H250V121H538V148H250V175H538V130H690V98" fill="none" stroke="#7b9b88" stroke-width="8" stroke-linejoin="round"/><path d="M110 82V130H250V67H538V94H250V121H538V148H250V175H538V130H690V98" fill="none" stroke="#f4faf5" stroke-width="3" stroke-linejoin="round"/><rect x="104" y="72" width="12" height="42" rx="3" fill="#b8d5d6" stroke="#709c9b"/><path d="M110 67V48M103 48H117" stroke="#577e7a" stroke-width="3"/>${gc.flame?'<path class="gc-flame" d="M690 77Q670 101 687 110Q711 108 698 87Q699 103 690 99Q680 94 690 77" fill="#ed9a54"/>':'<circle cx="690" cy="99" r="11" fill="#e5eae6"/>'}<text x="110" y="166" text-anchor="middle" font-size="21" fill="#176854">${gcFmt(temp(m.injector,'injector'),0)} °C</text><text x="400" y="209" text-anchor="middle" font-size="18" fill="#176854">${gcFmt(oven,1)} °C</text><text x="690" y="166" text-anchor="middle" font-size="21" fill="#176854">${gcFmt(temp(m.detector,'detector'),0)} °C</text><text x="110" y="212" text-anchor="middle" font-size="11" fill="#62786b">${gcFmt(m.volume,2)} µL · ${m.splitMode==='split'?m.split+':1 split':'splitless'}</text><text x="690" y="212" text-anchor="middle" font-size="11" fill="#62786b">${gc.flame?'Flame on · signal acquired':'Flame off'}</text>${r?r.components.map(c=>{if(c.tr!==null&&gc.time>c.tr+.08)return '';let pos=c.positions[idx],point=gcBandPoint(pos);if(c.tr!==null&&gc.time>=c.tr)point=[690,126];return `<circle cx="${point[0]}" cy="${point[1]}" r="6" fill="${c.color}" stroke="#fff" stroke-width="1.5"><title>${c.name} · ${pos>=1?'eluted':(pos*100).toFixed(0)+'% along schematic column'}</title></circle>`}).join(''):''}<text x="400" y="250" text-anchor="middle" font-size="10" fill="#6a8070">Bands are schematic · band migration and detector timing share the same numerical model</text></svg>`}
function gcChart(){if(gcIsMS(gc.run?.method)&&typeof gcMSLiveData==='function'){const d=gcMSLiveData();return d?msChromatogram(d):'<p>Open the MS window for direct ion acquisition.</p>'}const r=gc.run,W=800,H=300,l=62,right=20,top=24,bottom=46,duration=r?r.duration:Math.max(1,Number.isFinite(gcDuration(gc.method))?gcDuration(gc.method):1),index=gcIndex();let max=5;if(r)for(let i=0;i<=index;i++)max=Math.max(max,r.signal[i]*1.12);const x=t=>l+t/duration*(W-l-right),y=v=>H-bottom-v/max*(H-top-bottom);let trace='';if(r&&index>0){const stride=Math.max(1,Math.floor((index+1)/650));let points=[];for(let i=0;i<=index;i+=stride){let lo=i,hi=i;for(let j=i;j<=Math.min(index,i+stride-1);j++){if(r.signal[j]<r.signal[lo])lo=j;if(r.signal[j]>r.signal[hi])hi=j}for(let j of lo<hi?[lo,hi]:[hi,lo])points.push(`${x(r.times[j]).toFixed(2)},${y(r.signal[j]).toFixed(2)}`)}trace=`<polyline points="${points.join(' ')}" fill="none" stroke="#087e67" stroke-width="1.8"/>`}let selected=r?.peaks.find(p=>p.number===gc.selected);return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Live simulated FID chromatogram, ${gcFmt(gc.time,2)} minutes acquired">${Array.from({length:6},(_,i)=>{let t=i*duration/5,v=i*max/5;return `<line x1="${x(t)}" x2="${x(t)}" y1="${top}" y2="${H-bottom}" stroke="#edf1ed"/><text x="${x(t)}" y="${H-bottom+18}" font-size="10" text-anchor="middle" fill="#6f8175">${t.toFixed(1)}</text><line x1="${l}" x2="${W-right}" y1="${y(v)}" y2="${y(v)}" stroke="#edf1ed"/><text x="${l-8}" y="${y(v)+4}" font-size="10" text-anchor="end" fill="#6f8175">${v.toFixed(1)}</text>`}).join('')}${selected?`<rect x="${x(selected.left)}" y="${top}" width="${Math.max(2,x(selected.right)-x(selected.left))}" height="${H-bottom-top}" fill="#bde5ca" opacity=".45"/>`:''}<path d="M${l} ${top}V${H-bottom}H${W-right}" fill="none" stroke="#a9bcb0"/>${trace}${gcVisiblePeaks().map(p=>`<text x="${x(p.tr)}" y="${Math.max(top+12,y(r.signal[p.index])-9)}" text-anchor="middle" font-size="11" fill="#2b6050">${p.number}</text>`).join('')}${r?`<line x1="${x(gc.time)}" x2="${x(gc.time)}" y1="${top}" y2="${H-bottom}" stroke="#b1743d" stroke-dasharray="4 4"/>`:''}<text x="${W/2}" y="${H-8}" text-anchor="middle" font-size="12" fill="#56705e">Time from injection / min</text><text transform="translate(16 145) rotate(-90)" text-anchor="middle" font-size="11" fill="#56705e">FID response / pA (simulated)</text></svg>`}
function gcResults(){if(gcIsMS(gc.run?.method)&&typeof gcMSLiveData==='function'){const d=gcMSLiveData();return d?msPeakTable(d):'<p>No MS scans acquired.</p>'}let rows=gcVisiblePeaks(),total=rows.reduce((s,p)=>s+p.area,0);if(!rows.length)return '<p class="muted">No complete peaks integrated yet. Inject a sample and let the detector record the peak and its trailing edge.</p>';return `<div class="gc-table-wrap"><table class="gc-table"><thead><tr><th>Peak</th><th>Model component(s)</th><th>tR / min</th><th>Height / pA</th><th>Area / pA·s</th><th>Area %</th><th>Resolution to previous</th><th>Quality</th></tr></thead><tbody>${rows.map(p=>`<tr data-gc-peak="${p.number}" class="${gc.selected===p.number?'gc-selected':''}"><td>${p.number}</td><td>${p.members.join(' + ')||'Unassigned signal'}</td><td>${gcFmt(p.tr)}</td><td>${gcFmt(p.height)}</td><td>${gcFmt(p.area)}</td><td>${gcFmt(total?p.area/total*100:0,2)}</td><td>${p.resolution===null?'—':gcFmt(p.resolution,2)}</td><td>${p.partial?'Truncated':p.members.length>1?'Co-elution':p.overlap?'Partial resolution':'Integrated'}</td></tr>`).join('')}</tbody></table></div><p class="gc-click-note">Areas are baseline-corrected numerical integrations of the generated signal. FID response factors differ between compounds; area % is not automatically mass % or concentration.</p>`}
function gcWarnings(){if(!gc.run)return '';const warnings=gc.running||gc.paused?gc.run.warnings.filter(w=>!w.startsWith('Some components do not elute')&&!w.startsWith('Some peaks overlap')&&!w.startsWith('A peak is cut')):gc.run.warnings;return warnings.map(w=>`<p class="gc-notice gc-warn">${w}</p>`).join('')}
function gcHistory(){if(!gc.history.length)return '<p class="muted">Save a completed or stopped run to retain its method and peak measurements on this device.</p>';return `<div class="gc-table-wrap"><table class="gc-table"><thead><tr><th>Run</th><th>Column</th><th>Oven method</th><th>Injection</th><th>Peaks</th><th>Status</th></tr></thead><tbody>${gc.history.map((h,i)=>`<tr><td>${i+1}</td><td>${GC_COLUMNS[h.method.column]?.name||'Column'}</td><td>${h.method.ovenMode==='program'?h.method.initial+' → '+h.method.final+' °C':h.method.initial+' °C'}</td><td>${h.method.volume} µL</td><td>${h.peaks.length}</td><td>${h.status}</td></tr>`).join('')}</tbody></table></div>${gcSavedDetails()}`}
function gcMessage(message){gc.message=message;const el=document.getElementById('gcMessage');if(el)el.textContent=message}
function gcSync(){for(const button of document.querySelectorAll('[data-gc-action]')){const a=button.dataset.gcAction;const disabled=a==='inject'?(!gc.power||!gc.carrier||!gc.ready||!gcDetectorReady()||gcLocked()):a==='equilibrate'?(!gc.power||!gc.carrier||gcLocked()):a==='flame'?((!gc.ready&&!gc.flame)||gcLocked()):a==='carrier'?(!gc.power||gcLocked()):a==='power'||a==='demo'?gcLocked():a==='save'?(gcIsMS(gc.run?.method)||!gc.run||gc.running||gc.paused||gc.run.saved):a==='export-peaks'?(!gc.run||!gcVisiblePeaks().length):a==='export-trace'?(!gc.run||gc.time<=0):a==='pause'||a==='stop'?(!gc.running&&!gc.paused):false;button.disabled=disabled||(gseq.active&&['inject','equilibrate','flame','carrier','power','demo'].includes(a))}let s=document.getElementById('gcState');if(s)s.textContent=gcStatus();let d=document.getElementById('gcDuration');if(d)d.textContent=gcFmt(gcDuration(gc.method),2)+' min'}
function gcPaint(){if(typeof page==='undefined'||page!=='instrumentation')return;let el=document.getElementById('gcInstrument');if(!el)return;el.innerHTML=gcInstrument();document.getElementById('gcChart').innerHTML=gcChart();document.getElementById('gcResults').innerHTML=gcResults();document.getElementById('gcTime').textContent=gcFmt(gc.time,2)+' min';document.getElementById('gcOvenValue').textContent=gcFmt(gcActualOven(),1)+' °C';document.getElementById('gcSignal').textContent=gcSignalText();document.getElementById('gcPeakCount').textContent=gcIsMS(gc.run?.method)&&typeof gcMSPeakCount==='function'?gcMSPeakCount():gcVisiblePeaks().length;document.getElementById('gcProgress').value=gc.run?gc.time/gc.run.duration:0;gcSync()}
function gcEquilibrate(options={}){if(typeof gseq!=='undefined'&&gseq.active&&!gseq.launching)return;if(gcLocked()||!gc.power||!gc.carrier)return;const errors=gcValidation(gc.method);if(errors.length){gcMessage(errors.join(' '));return}if(gc.run?.completed||gc.run?.stopped)gc.preparingNext=true;if(typeof gcMSWarmStart==='function')gcMSWarmStart();gc.warmFrom={injector:gc.actualInjector,detector:gc.actualDetector,oven:gcActualOven()};gc.warming=true;gc.ready=false;gc.warm=0;gc.flame=false;gc.finishedTemp=null;gcMessage('Equilibrating the injector, oven and FID to their setpoints. Heating is accelerated for this simulation.');gcRender();const start=performance.now();function warm(now){gc.warm=Math.min(1,(now-start)/2200);gcPaint();if(typeof gcMSPaint==='function')gcMSPaint(now);if(gc.warm>=1){gc.warming=false;gc.ready=true;gc.actualInjector=gc.method.injector;if(!gcIsMS())gc.actualDetector=gc.method.detector;gc.actualOven=gc.method.initial;if(typeof gcMSWarmFinish==='function')gcMSWarmFinish();if(options.keepFlame&&gc.power&&gc.carrier&&gc.method.detector>150)gc.flame=true;gcMessage(gcIsMS()?'GC and MS heated zones are stable. Prepare MS vacuum if needed, then inject.':gc.flame?'Temperatures are stable and the FID is lit. Inject the loaded sample to start the next run.':'Temperatures are stable. Ignite the FID, then inject the prepared sample.');gcRender();if(typeof gcMSRefresh==='function'&&gcIsMS())gcMSRefresh()}else gc.raf=requestAnimationFrame(warm)}gc.raf=requestAnimationFrame(warm)}
function gcStart(){if(typeof gseq!=='undefined'&&gseq.active&&!gseq.launching)return false;if(gcLocked()||!gc.power||!gc.carrier||!gc.ready||!gcDetectorReady()){gcMessage('Power on, enable carrier gas and prepare the selected detector before injection.');return false}const errors=gcValidation(gc.method);const sample=gcSamples();if(gc.sample!=='blank'&&!sample.length)errors.push('Choose at least one compound, or select a blank.');if(sample.some(c=>!Number.isFinite(c.concentration)||c.concentration<=0||c.concentration>20))errors.push('Use component concentrations greater than 0 and no more than 20 mg/mL.');if(errors.length){gcMessage(errors.join(' '));return false}try{const nextRun=gcSimulate({...gc.method},sample);if(typeof gcRememberRun==='function')gcRememberRun();gc.run=nextRun;gc.preparingNext=false}catch(e){gcMessage(e.message);return false}gc.run.calibration=typeof gcCalRunTag==='function'?gcCalRunTag():null;gc.time=0;gc.selected=null;gc.paused=false;gc.running=true;gc.finishedTemp=null;gcMessage('Sample injected. Bands are migrating through the column and the selected detector is acquiring data.');if(gcIsMS()&&typeof gcMSBeginRun==='function')gcMSBeginRun();gcRender();gcTick();return true}
function gcTick(){cancelAnimationFrame(gc.raf);let last=performance.now(),painted=last;function tick(now){if(!gc.running)return;gc.time=Math.min(gc.run.duration,gc.time+(now-last)/60000*gc.speed);last=now;if(now-painted>=50){gcPaint();if(typeof gcMSPaint==='function')gcMSPaint(now);painted=now}if(gc.time>=gc.run.duration){gc.running=false;gc.paused=false;gc.run.completed=true;if(typeof gcCalibrationFinished==='function')gcCalibrationFinished(gc.run);gc.ready=false;gc.finishedTemp=gcOven(gc.run.method,gc.time);gc.actualOven=gc.finishedTemp;gcMessage('Run complete. Review the peaks, then use Run another sample in the Load sample area to prepare the next vial. You can export the current trace before the next injection.');if(gcIsMS(gc.run.method)&&typeof gcMSUpdateRun==='function')gcMSUpdateRun(true);if(typeof gcSequenceFinished==='function')gcSequenceFinished(gc.run);gcRender()}else gc.raf=requestAnimationFrame(tick)}gc.raf=requestAnimationFrame(tick)}
function gcPause(){if(gc.running){gc.running=false;gc.paused=true;cancelAnimationFrame(gc.raf);gcMessage('Acquisition paused for inspection. Resume to continue the virtual run.');gcRender()}else if(gc.paused){gc.paused=false;gc.running=true;gcMessage('Acquisition resumed.');gcRender();gcTick()}}
function gcStop(){if(typeof gseq!=='undefined'&&gseq.active){gcSequenceStop();return}if(!gc.running&&!gc.paused)return;cancelAnimationFrame(gc.raf);gc.running=false;gc.paused=false;gc.ready=false;gc.run.stopped=true;gc.finishedTemp=gcOven(gc.run.method,gc.time);gc.actualOven=gc.finishedTemp;if(gcIsMS(gc.run.method)&&typeof gcMSUpdateRun==='function')gcMSUpdateRun(true);gcMessage('Acquisition stopped. Only signal up to the stopping time is acquired; later components and incomplete peaks are not fully measured. Re-equilibrate before reinjection.');gcRender()}
function gcDownload(name,rows){const csv=rows.map(row=>row.map(value=>'"'+String(value??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function gcExport(type){if(!gc.run||gcIsMS(gc.run.method))return;const r=gc.run,m=r.method;if(type==='trace'){const rows=[['time_min','FID_signal_pA_simulated','baseline_pA','oven_C']];for(let i=0;i<=gcIndex();i++)rows.push([gcFmt(r.times[i],6),gcFmt(r.signal[i],6),gcFmt(gcBaseline(r.times[i]),6),gcFmt(gcOven(m,r.times[i]),3)]);gcDownload('SIMLAB-GCFID-acquired-trace.csv',rows)}else{let peaks=gcVisiblePeaks(),sum=peaks.reduce((s,p)=>s+p.area,0),rows=[['peak','model_components','retention_min','height_pA_simulated','area_pA_s_simulated','area_percent','quality','column','injection_uL','injector_C','initial_oven_C','final_oven_C','ramp_C_per_min','carrier_mL_per_min']];for(const p of peaks)rows.push([p.number,p.members.join(' + '),gcFmt(p.tr,6),gcFmt(p.height,6),gcFmt(p.area,6),gcFmt(sum?p.area/sum*100:0,3),p.partial?'Truncated':p.members.length>1?'Co-elution':p.overlap?'Partial resolution':'Integrated',GC_COLUMNS[m.column].name,m.volume,m.injector,m.initial,m.ovenMode==='program'?m.final:m.initial,m.ovenMode==='program'?m.ramp:0,m.flow]);gcDownload('SIMLAB-GCFID-peak-table.csv',rows)}}
function gcPreset(value){gc.sample=value;if(value==='blank')gc.mix={};else if(value==='hydrocarbons')gc.mix={hexane:.5,heptane:.5,toluene:.5,octane:.5,ethylbenzene:.5};else if(value==='polarity')gc.mix={acetone:.5,ethanol:.5,hexane:.5,toluene:.5};else if(GC_COMPOUNDS.some(c=>c.id===value))gc.mix={[value]:.5};gcRender()}
document.addEventListener('input',e=>{if(typeof page==='undefined'||page!=='instrumentation'||gcLocked()||(typeof gseq!=='undefined'&&gseq.active))return;const t=e.target,key=t.dataset.gcField;if(key&&typeof gcDefaults()[key]==='number'){gc.method[key]=Number(t.value);if(!['volume','split'].includes(key)){gc.ready=false;gc.flame=false;gc.finishedTemp=null;}gcSave()}else if(t.dataset.gcConcentration){gc.mix[t.dataset.gcConcentration]=Number(t.value);gc.sample='custom';gcSave()}});
document.addEventListener('change',e=>{if(typeof page==='undefined'||page!=='instrumentation')return;const t=e.target;if(t.id==='gcSpeed'){gc.speed=Number(t.value);return}if(gcLocked()||(typeof gseq!=='undefined'&&gseq.active))return;if(t.dataset.gcField){const key=t.dataset.gcField;gc.method[key]=typeof gcDefaults()[key]==='number'?Number(t.value):t.value;if(!['volume','split','splitMode','noise'].includes(key)){gc.ready=false;gc.flame=false;gc.finishedTemp=null;gcMessage('Method changed. Re-equilibrate the instrument and ignite the FID before the next run.')}if(key==='detectorType'&&typeof gms!=='undefined'){gms.on=false;gms.autoEnable=false;}gcSave();if(['detectorType','column','ovenMode','splitMode'].includes(key))gcRender();else gcPaint()}else if(t.id==='gcNoise'){gc.method.noise=t.checked;gcSave()}else if(t.id==='gcSample'){gcPreset(t.value)}else if(t.dataset.gcCompound){const id=t.dataset.gcCompound;if(t.checked)gc.mix[id]=.5;else delete gc.mix[id];gc.sample='custom';gcRender()}else if(t.dataset.gcConcentration){gc.mix[t.dataset.gcConcentration]=Number(t.value);gc.sample='custom';const select=document.getElementById('gcSample');if(select)select.value='custom';gcSave()}});
document.addEventListener('click',e=>{if(typeof page==='undefined'||page!=='instrumentation')return;let row=e.target.closest('[data-gc-peak]');if(row){gc.selected=Number(row.dataset.gcPeak);gcPaint();return}const action=e.target.closest('[data-gc-action]')?.dataset.gcAction;if(!action)return;if(action==='pause'){gcPause();return}if(action==='stop'){gcStop();return}if(action==='export-peaks'){gcExport('peaks');return}if(action==='export-trace'){gcExport('trace');return}if(gcLocked()||(typeof gseq!=='undefined'&&gseq.active))return;if(action==='power'){gc.power=!gc.power;gc.ready=false;gc.flame=false;gc.finishedTemp=null;if(!gc.power){gc.carrier=false;gc.actualInjector=25;gc.actualDetector=25;gc.actualOven=25;if(typeof gcMSReset==='function')gcMSReset();}gcMessage(gc.power?'Instrument powered on. Enable carrier gas, then equilibrate.':'Instrument off. Previous acquired data remain available.');gcRender()}else if(action==='carrier'&&gc.power){gc.carrier=!gc.carrier;gc.ready=false;gc.flame=false;gcMessage(gc.carrier?'Carrier gas is on. Equilibrate the selected temperatures.':'Carrier gas is off. Injection is disabled.');gcRender()}else if(action==='equilibrate'){gcEquilibrate()}else if(action==='flame'){if(gc.flame){gc.flame=false;gcMessage('FID extinguished. Reignite before injection.')}else if(gc.ready&&gc.carrier&&gc.method.detector>150){gc.flame=true;gcMessage('FID ignited. The detector baseline is stable; the instrument is ready for injection.')}else gcMessage('Equilibrate the instrument with FID temperature above 150 °C before ignition.');gcRender()}else if(action==='inject'){gcStart()}else if(action==='demo'){gc.method=gcDefaults();gc.ready=false;gc.flame=false;gc.finishedTemp=null;gcPreset('hydrocarbons');gcMessage('Demonstration method loaded. Power on, enable carrier, equilibrate, ignite the FID, then inject.');gcRender()}else if(action==='save'&&gc.run&&!gc.run.saved){const r=gc.run;gc.history.push({method:{...r.method},sample:r.components.map(c=>({id:c.id,concentration:c.concentration})),peaks:gcVisiblePeaks().map(p=>({...p})),acquired:gc.time,status:r.completed?'Complete':'Stopped'});gc.history=gc.history.slice(-8);r.saved=true;gcMessage(gcSave()?'Run summary saved in the notebook on this device.':'Run summary is available in this session; browser storage is unavailable.');gcRender()}});

function gcSavedDetails(){return gc.history.map((h,i)=>`<details class="gc-detail"><summary>Run ${i+1} measurements · ${h.status}</summary><p>${GC_COLUMNS[h.method.column]?.name||'Column'} · injector ${h.method.injector} °C · injection ${h.method.volume} µL · acquired ${gcFmt(h.acquired,2)} min. This summary retains measurements, not the full trace.</p><div class="gc-table-wrap"><table class="gc-table"><thead><tr><th>Peak</th><th>Model component(s)</th><th>tR / min</th><th>Height / pA</th><th>Area / pA·s</th></tr></thead><tbody>${h.peaks.map(p=>`<tr><td>${p.number}</td><td>${p.members.join(' + ')}</td><td>${gcFmt(p.tr)}</td><td>${gcFmt(p.height)}</td><td>${gcFmt(p.area)}</td></tr>`).join('')}</tbody></table></div></details>`).join('')}
